(async () => {
  const page = figma.root.findChild(n=>n.name==='03 · Workspace');
  await figma.setCurrentPageAsync(page);

  const navMap = {
    'Icon_Nav_Dashboard':'16:2',
    'Icon_Nav_Timeline':'18:139',
    'Icon_Nav_Task':'19:448',
    'Icon_Nav_Settings':'19:1080',
    'Icon_Nav_Messages':'19:1168',
    'Icon_Nav_Files':'19:781'
  };

  function setNav(node, screenId){
    const targetId = navMap[node.name];
    if(!targetId) return 0;
    if(targetId===screenId) return 0; // skip self
    node.reactions=[{
      actions:[{ type:'NODE', destinationId:targetId, navigation:'NAVIGATE', transition:{type:'DISSOLVE',duration:200,easing:{type:'EASE_IN_AND_OUT'}} }],
      trigger:{type:'ON_CLICK'}
    }];
    return 1;
  }

  const report=[];
  page.children.forEach(function(scr){
    if(scr.type!=='FRAME') return;
    const id = /^0[1-6]/.exec(scr.name);
    if(!id) return;
    const screenId = scr.id;
    let navCount=0;
    scr.findAll(function(n){
      if(n.type==='INSTANCE' && navMap[n.name]) navCount += setNav(n, screenId);
    });
    report.push(scr.name+': nav='+navCount);
  });

  // Wire Dashboard message avatars -> Messages screen (19:1168)
  const dash = page.children.find(c=>c.type==='FRAME' && c.name==='01_Dashboard');
  const msgPanel = dash.children.find(c=>c.name==='Messages');
  let msgCount=0;
  if(msgPanel){
    msgPanel.children.forEach(function(av){
      if(av.type==='INSTANCE' && /^Avatar_/.test(av.name)){
        av.reactions=[{
          actions:[{ type:'NODE', destinationId:'19:1168', navigation:'NAVIGATE', transition:{type:'DISSOLVE',duration:200,easing:{type:'EASE_IN_AND_OUT'}} }],
          trigger:{type:'ON_CLICK'}
        }];
        msgCount++;
      }
    });
  }
  report.push('Dashboard messages -> 06: '+msgCount);

  // write report to a text frame
  await figma.loadFontAsync({family:'DM Sans', style:'Regular'});
  const ok = figma.createFrame(); ok.name='__FINAL_OK'; ok.x=-1000; ok.y=0; ok.resize(520,400);
  const t=figma.createText(); t.fontName={family:'DM Sans',style:'Regular'};
  t.characters=report.join('\n');
  ok.appendChild(t); page.appendChild(ok);
  figma.closePlugin();
})();

